import{z as B,x as i,o as t,c as S,q as r,j as n,D as E,d as A,s as o,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const H=JSON.parse('{"title":"HSTS 与钉扎对照","description":"","frontmatter":{"title":"HSTS 与钉扎对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hsts.md","filePath":"cs/hsts.md","lastUpdated":1791063341000}'),d={name:"cs/hsts.md"};function T(p,a,h,m,D,c){const s=i("Mermaid");return t(),S("div",null,[a[2]||(a[2]=r('<h1 id="hsts-与钉扎对照" tabindex="-1">HSTS 与钉扎对照 <a class="header-anchor" href="#hsts-与钉扎对照" aria-label="Permalink to &quot;HSTS 与钉扎对照&quot;">​</a></h1><div class="epigraph"><p>HSTS 让浏览器记住「该主机只走 HTTPS」，减少第一次明文被劫持成假站点的窗口；钉扎则把信任锚收得更窄，失败模式也更硬。</p><footer>—— 据 RFC 6797 HSTS；Anderson 对钉扎与 PKI 的整理；对照 RFC 8446</footer></div><p><a href="/cs/mitm">上一课</a>说明未认证的加密等于与中间人建了两条会话。本课不重做假冒几何。缺口是浏览器的第一次访问：用户敲 <code>http://</code>，或被降级。HSTS 用响应头声明只 HTTPS 及期限。证书钉扎对照：只接受某公钥。DoS 下一课打的是 A 轴。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>中间人课留下「证书关掉缺口」。用户与书签仍可能走 80 端口。<a href="/cs/http-tls-entry">TLS 入口</a> 假定已经在 TLS 上。HSTS：浏览器为该名字存「强制 HTTPS」，连内部链也升级。预加载列表把第一次访问也收进已知集。钉扎：额外约束叶子或中间 CA，CA 误签也不收——但钉错则自毁访问。缺口是<strong>客户端政策补 PKI</strong>。</p><p><span class="marginnote">HSTS 不修错误的证书链，只修协议降级与明文入口。钉扎在浏览器里已大幅收缩，对照即可，不把已废弃的 HPKP 细节当现行主干。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>服务器在 HTTPS 响应里声明 max-age。客户端之后拒绝明文与未认证升级。防御降级：不接受「这次用弱套件」。钉扎若用，必须有备份键与过期，否则运维事故变成全局不可用。本课不写如何伪造证书。</p><p><span class="marginnote">数字实例：<code>max-age=31536000</code> 就是「记住一年」。它只能延长、不能立即撤销——想反悔只能把新值设为 0，但已存进浏览器的旧期限到期前，客户端依旧拒绝明文。所以上线前必须确认整个域名的 HTTPS 稳定可用。</span></p>',9)),(t(),n(l,null,{default:E(()=>[o(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20HTTP%5B%22%E6%98%8E%E6%96%87%E5%85%A5%E5%8F%A3%22%5D%20--%3E%20HSTS%5B%22%E8%AE%B0%E4%BD%8F%E5%8F%AA%20HTTPS%22%5D%0A%20%20HSTS%20--%3E%20TLS%5B%22%E5%BC%BA%E5%88%B6%E6%8F%A1%E6%89%8B%20RFC%208446%22%5D%0A%20%20PIN%5B%22%E9%92%89%E6%89%8E%22%5D%20--%3E%20NARROW%5B%22%E6%9B%B4%E7%AA%84%E9%94%9A%E3%80%81%E6%9B%B4%E7%A1%AC%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[A("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"HSTS 把用户的第一次明文窗口缩小，服务真实性与保密的入口一致性。它依赖一次真实的 HTTPS 才能种下策略（或预加载）。中间人若在种策略前就在路径上，HSTS 尚未生效——预加载是补丁。后课 DoS 不靠假证书，靠资源耗尽。",-1)),a[5]||(a[5]=e("p",null,"保护的窗口从什么时候开始算？把首次与后续访问并排看：",-1)),(t(),n(l,null,{default:E(()=>[o(s,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20F%5B%22%E9%A6%96%E6%AC%A1%E8%AE%BF%E9%97%AE%EF%BC%9A%E7%AD%96%E7%95%A5%E8%BF%98%E6%B2%A1%E7%A7%8D%E4%B8%8B%22%5D%0A%20%20%20%20U1%5B%22%E7%94%A8%E6%88%B7%E6%95%B2%20http%3A%2F%2F%22%5D%20--%3E%20M%5B%22%E4%B8%AD%E9%97%B4%E4%BA%BA%E5%8F%AF%E5%8A%AB%E6%8C%81%E6%88%96%E9%99%8D%E7%BA%A7%22%5D%0A%20%20end%0A%20%20subgraph%20S%5B%22%E5%90%8E%E7%BB%AD%E8%AE%BF%E9%97%AE%EF%BC%9A%E5%B7%B2%E7%A7%8D%20HSTS%22%5D%0A%20%20%20%20U2%5B%22%E6%B5%8F%E8%A7%88%E5%99%A8%E5%86%85%E9%83%A8%E6%94%B9%E5%86%99%E4%B8%BA%20https%3A%2F%2F%22%5D%20--%3E%20T%5B%22%E6%8B%92%E7%BB%9D%E6%98%8E%E6%96%87%E4%B8%8E%E6%9C%AA%E8%AE%A4%E8%AF%81%E5%8D%87%E7%BA%A7%22%5D%0A%20%20end%0A%20%20F%20--%3E%7C%22%E4%B8%80%E6%AC%A1%E7%9C%9F%E5%AE%9E%20HTTPS%20%E7%A7%8D%E4%B8%8B%E7%AD%96%E7%95%A5%22%7C%20S%0A%20%20PRE%5B%22%E9%A2%84%E5%8A%A0%E8%BD%BD%E5%88%97%E8%A1%A8%22%5D%20-.-%3E%7C%22%E9%A6%96%E6%AC%A1%E4%B9%9F%E7%9B%B4%E6%8E%A5%E8%B7%B3%E8%BF%87%E6%98%8E%E6%96%87%22%7C%20U2%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">直觉类比：HSTS 像店家在门口贴告示「本店只走安全通道」，来过的客人记住了；但没来过的第一次仍可能被人引去假入口——预加载列表相当于出发前先查官方攻略，把「第一次」也提前保护住。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全部浏览器 UI 锁图标史写进主干。可用如何被洪水与放大打穿，下一课。</p><p>后课默认：站点可要求客户端拒绝明文。CIA 的 A 仍可单独失败。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>HSTS 强制后续只走 HTTPS，缩小降级窗口。</li><li>钉扎更窄更脆，仅作对照。</li><li>DoS 与放大下一课。</li><li>出处：RFC 6797；Anderson；RFC 8446。</li></ul><p><span class="marginnote">常见误区：初学者容易把钉扎（pinning）当成「更安全的 HSTS」。实际上钉扎把信任锚收窄到指定公钥，证书轮换、CDN 换商、私钥泄露换锁，任何一步没同步备份键，整个站点对装了钉扎策略的客户端直接不可访问——更硬的失败模式是双刃剑。</span></p>',7))])}const P=B(d,[["render",T]]);export{H as __pageData,P as default};
